#include <bits/stdc++.h>
#define int long long int
using namespace std;

void solve() {
    
    int n;
    cin >> n;
    
    int m = n*3;
    vector<int> v(m);
    for (int i = 0;i<m;i++) {
        cin >> v[i];
    }
    
    sort(v.rbegin(),v.rend());
    
    vector<int> p(m+1,0);
    for (int i = 0;i<m;i++) {
        p[i+1] = p[i]+v[i];
    }
    
    int ans = 0;
    for (int i = 0;i<=n;i++) {
        int mx = n-i;
        int temp = 0;
        if (mx > 0) {
            int start = 0;
            int end = mx-1;
            int best = -1;
            
            while (start <= end) {
                
                int mid = (start + end)/2;
                int q = i+2*mid;
                int r = 3*n-2*i-mid;
                int dif = v[q] + v[q+1] - 3LL*v[r-1];
                if (dif >= 0) {
                    best = mid;
                    start = mid+1;
                } else {
                    end = mid-1;
                }
            }
            temp = best + 1;
        }
        
        int cur = 2LL*p[i]+p[i+2*temp] + 3LL*p[3*n-2*i-temp];
        ans = max(ans,cur);
    }
    
    cout << ans << endl;
}
int32_t main() {

    int t;
    cin >> t;
    
    while (t--) {
        solve();
    }
}
